import Model from 'flarum/common/Model';

/** A calendar category (`calendar-categories`), as the store keeps it. api.ts turns it into the plain CalCategory the views use. */
export default class CalendarCategory extends Model {
  name = Model.attribute('name');
  slug = Model.attribute('slug');
  color = Model.attribute('color');
  rsvp = Model.attribute('rsvp');
  goingLabel = Model.attribute('goingLabel');
  interestedLabel = Model.attribute('interestedLabel');
  position = Model.attribute('position');
}
flarum.reg.add('ernestdefoe-calendar', 'common/models/CalendarCategory', CalendarCategory);